// frontend/src/App.js
import React, { useState, useContext } from "react";
import { AuthProvider, AuthContext } from "./context/AuthContext";
import Navbar from "./components/Navbar";
import LoginPage from "./components/LoginPage";
import RegisterPage from "D:\backend\Files (2)\frontend\src\components\RegisterPage.js";
import EventList from "./components/EventList";
import EventDetails from "./components/EventDetails";
import MyEvents from "./components/MyEvents";
import AdminDashboard from "./components/AdminDashboard";
import MapView from "./components/MapView";
import EventCalendarView from "./components/EventCalendarView";
import "./styles.css";

const AppContent = () => {
  const [page, setPage] = useState("events");
  const [selectedEventId, setSelectedEventId] = useState(null);
  const { user, loading } = useContext(AuthContext);

  if (loading) {
    return <div className="loading-container"><p>Loading...</p></div>;
  }

  return (
    <>
      <Navbar setPage={setPage} />
      <div className="main-layout">
        {page === "login" && <LoginPage />}
        {page === "register" && <RegisterPage />}
        {page === "events" && (
          <div className="events-main">
            <EventList onSelect={(id) => { setSelectedEventId(id); }} />
            <EventDetails eventId={selectedEventId} />
          </div>
        )}
        {page === "myEvents" && <MyEvents />}
        {page === "admin" && user?.role === "admin" && <AdminDashboard />}
        {page === "admin" && user?.role !== "admin" && <div className="error-message">Access Denied</div>}
        {page === "map" && <MapView />}
        {page === "calendar" && <EventCalendarView />}
      </div>
    </>
  );
};

const App = () => {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
};

export default App;
